for (const item of $input.all()) {
  const body = item.json.body;
  const filters = [];


  // filter by assignee, status, priority
  if (body.assignee) filters.push(`{Assignee}='${body.assignee.toLowerCase().trim()}'`);

  if (body.status)   filters.push(`{Status}='${body.status.trim().charAt(0).toUpperCase() + body.status.trim().slice(1).toLowerCase()}'`);

  if (body.priority) filters.push(`{Priority}='${body.priority.trim().charAt(0).toUpperCase() + body.priority.trim().slice(1).toLowerCase()}'`);

  const formula = filters.length === 0 ? ''
    : filters.length === 1 ? filters[0]
    : `AND(${filters.join(',')})`;

  return { json: { ...body, filterByFormula: formula } };
}

